import { randomBytes } from 'node:crypto';
import { existsSync } from 'node:fs';
import { chmod, mkdir, writeFile } from 'node:fs/promises';
import path from 'node:path';

export interface InitResult {
  readonly path: string;
  readonly created: boolean;
}

/** Hex only, so generated values are safe inside URLs and shell-free env files. */
const secret = (bytes: number): string => randomBytes(bytes).toString('hex');

export function renderEnv(): string {
  return [
    '# Generated by `qos init`. Local secrets: never commit, never share.',
    'POSTGRES_USER=qos',
    `POSTGRES_PASSWORD=${secret(24)}`,
    'POSTGRES_DB=qualityos',
    'POSTGRES_PORT=55432',
    `FILE_URL_SECRET=${secret(32)}`,
    'API_PORT=3001',
    'WEB_PORT=3000',
    'LOG_LEVEL=info',
    '',
  ].join('\n');
}

/**
 * Creates infra/compose/.env with fresh secrets. An existing file is never overwritten:
 * replacing the database password would lock the stack out of its own data volume.
 */
export async function initEnv(repoRoot: string): Promise<InitResult> {
  const dir = path.join(repoRoot, 'infra', 'compose');
  const file = path.join(dir, '.env');
  if (existsSync(file)) return { path: file, created: false };
  await mkdir(dir, { recursive: true });
  await writeFile(file, renderEnv(), { flag: 'wx', mode: 0o600 });
  await chmod(file, 0o600).catch(() => undefined); // no effect on Windows; harmless
  return { path: file, created: true };
}
